// HasLibrary applies the HasEdge predicate on the "library" edge.
func HasLibrary() predicate.LibraryOptions {
	return predicate.LibraryOptions(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, LibraryTable, LibraryColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLibraryWith applies the HasEdge predicate on the "library" edge with a given conditions (other predicates).
func HasLibraryWith(preds ...predicate.Library) predicate.LibraryOptions {
	return predicate.LibraryOptions(func(s *sql.Selector) {
		step := newLibraryStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.LibraryOptions) predicate.LibraryOptions {
	return predicate.LibraryOptions(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.LibraryOptions) predicate.LibraryOptions {
	return predicate.LibraryOptions(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.LibraryOptions) predicate.LibraryOptions {
	return predicate.LibraryOptions(sql.NotPredicates(p))
}
